// n8n Code Node - Clean JSON text output
// This code extracts and cleans the text from your AI node output

// Get the input data (adjust the path based on your n8n setup)
const inputData = $input.all();

// Function to clean markdown and format text
function cleanText(text) {
  return text
    // Remove markdown bold formatting
    .replace(/\*\*(.*?)\*\*/g, '$1')
    // Remove markdown italic formatting  
    .replace(/\*(.*?)\*/g, '$1')
    // Clean up multiple spaces
    .replace(/\s+/g, ' ')
    // Clean up multiple line breaks (keep double line breaks for paragraphs)
    .replace(/\n{3,}/g, '\n\n')
    // Remove leading/trailing whitespace
    .trim();
}

// Process each item in the input
const cleanedItems = inputData.map(item => {
  let cleanedText = '';

  // Check if the item has the JSON structure you showed
  if (item.json && Array.isArray(item.json)) {
    // Extract text from each object in the array
    cleanedText = item.json
      .map(obj => obj.text || '')
      .join('\n\n')
      .replace(/\n\n+/g, '\n\n'); // Clean up excessive line breaks
  } else if (typeof item.json === 'string') {
    // If it's already a string, clean it directly
    cleanedText = item.json;
  } else if (item.json && item.json.text) {
    // If it's an object with a text property
    cleanedText = item.json.text;
  } else {
    // Fallback: stringify the entire object
    cleanedText = JSON.stringify(item.json, null, 2);
  }

  // Apply text cleaning
  cleanedText = cleanText(cleanedText);

  return {
    json: {
      cleanedText: cleanedText,
      originalLength: JSON.stringify(item.json).length,
      cleanedLength: cleanedText.length
    }
  };
});

// Return the cleaned data
return cleanedItems;
